<div class="mx-auto flex max-w-[1120px] flex-col gap-10 px-4 py-10 md:gap-12 md:px-6 md:py-16">
<header><h1 class="mb-4 text-[40px] leading-tight font-bold tracking-tighter md:text-6xl"><?= e($title) ?></h1><p class="font-serif text-xl text-slate-700 dark:text-slate-300"><?= e($description) ?></p></header>
<div class="rounded-[14px] border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
<div class="flex flex-wrap items-center gap-2"><span class="eyebrow w-24"><?= e(__('category')) ?></span><a class="button-secondary rounded-full" href="<?= e('/' . $locale . '/posts') ?>" <?= $selected === null ? 'aria-current="page"' : '' ?>><?= e(__('all')) ?></a>
<?php foreach ($categories as $term): ?><a class="button-secondary rounded-full" href="<?= e('/' . $locale . '/categories/' . rawurlencode($term['slug'])) ?>" <?= $suffix === '/categories/' . rawurlencode($term['slug']) ? 'aria-current="page"' : '' ?>><?= e($term['name']) ?></a><?php endforeach ?></div>
<div class="mt-4 flex flex-wrap items-center gap-1.5 border-t border-slate-100 pt-4 dark:border-slate-800"><span class="eyebrow w-24"><?= e(__('tags')) ?></span><?php foreach ($tags as $term): ?><a class="tag" href="<?= e('/' . $locale . '/tags/' . rawurlencode($term['slug'])) ?>" <?= $suffix === '/tags/' . rawurlencode($term['slug']) ? 'aria-current="page"' : '' ?>>#<?= e($term['name']) ?></a><?php endforeach ?></div>
</div>
<?php foreach ($groups as $year => $months): ?><section class="flex flex-wrap gap-x-12 gap-y-6"><h2 class="w-40 text-5xl leading-none font-bold tracking-tight text-slate-500 dark:text-slate-500"><?= e($year) ?></h2><div class="min-w-0 flex-[999_1_560px] space-y-8">
<?php foreach ($months as $month => $posts): ?><div><h3 class="eyebrow mb-2 text-orange-700 dark:text-orange-400"><?= e(localized_date($month . '-01', 'LLLL')) ?></h3>
<?php foreach ($posts as $post): ?><a href="<?= e('/' . $locale . '/posts/' . rawurlencode($post['slug'])) ?>" class="flex flex-wrap items-baseline gap-x-5 gap-y-1 border-t border-slate-200 py-4 dark:border-slate-800"><time class="w-12 font-mono text-sm text-slate-600 dark:text-slate-400" datetime="<?= e($post['published_at']) ?>"><?= e(localized_date($post['published_at'], 'dd')) ?></time><span class="flex-[999_1_320px] text-xl font-semibold tracking-tight"><?= e($post['title']) ?></span><span class="text-sm text-slate-600 dark:text-slate-400"><?= e($post['category_name'] ?? '') ?> · <?= e(__('reading_minutes', ['minutes' => $post['reading_minutes']])) ?></span></a><?php endforeach ?></div><?php endforeach ?>
</div></section><?php endforeach ?>
<?php if (!$groups): ?><p><?= e(__('empty_posts')) ?></p><?php endif ?>
<nav aria-label="<?= e(__('pagination')) ?>" class="flex flex-wrap items-center justify-between gap-4">
<?php if ((int) $page > 1): ?><a class="button-secondary" rel="prev" href="<?= e('/' . $locale . $suffix . ((int) $page > 2 ? '?page=' . ((int) $page - 1) : '')) ?>">← <?= e(__('newer')) ?></a><?php else: ?><span class="button-secondary opacity-50" aria-disabled="true">← <?= e(__('newer')) ?></span><?php endif ?>
<div class="flex flex-wrap gap-1"><?php for ($n = max(1, (int) $page - 2); $n <= min($totalPages, (int) $page + 2); $n++): ?><a class="inline-flex size-11 items-center justify-center rounded-lg font-mono <?= $n === (int) $page ? 'bg-slate-900 text-white dark:bg-slate-100 dark:text-slate-900' : '' ?>" <?= $n === (int) $page ? 'aria-current="page"' : '' ?> href="<?= e('/' . $locale . $suffix . ($n > 1 ? '?page=' . $n : '')) ?>"><?= e($n) ?></a><?php endfor ?></div>
<?php if ((int) $page < $totalPages): ?><a class="button-primary" rel="next" href="<?= e('/' . $locale . $suffix . '?page=' . ((int) $page + 1)) ?>"><?= e(__('older')) ?> →</a><?php else: ?><span class="button-secondary opacity-50" aria-disabled="true"><?= e(__('older')) ?> →</span><?php endif ?>
</nav></div>
